# -*- coding: utf-8 -*-
"""
Interface for natsort to access fastnumbers functions without
having to worry if it is actually installed.
"""
from __future__ import absolute_import, division, print_function, unicode_literals

try:
    from distutils.version import StrictVersion
except ImportError:
    # Python 3.12 removed distutils (PEP 632), and this module is imported by
    # natsort.utils on every `import natsort`. The unconditional distutils
    # import that used to sit here made natsort itself unimportable on 3.12,
    # even though the only thing StrictVersion is used for below is gating the
    # OPTIONAL fastnumbers speed-up - the fallback right there already covers
    # fastnumbers being absent. Comparing the numeric prefix directly keeps the
    # same >= 2.0.0 rule without the removed module.
    # (natsort 8.x dropped Python 2 support, so it cannot be adopted wholesale
    # by a bundle that still runs on IronPython 2.7.)
    class StrictVersion(object):
        """Minimal stand-in for distutils.version.StrictVersion."""

        def __init__(self, vstring):
            self.version = tuple(
                int(part) for part in str(vstring).split(".")[:3] if part.isdigit()
            )

        def __lt__(self, other):
            return self.version < other.version

        def __ge__(self, other):
            return self.version >= other.version


# If the user has fastnumbers installed, they will get great speed
# benefits. If not, we use the simulated functions that come with natsort.
try:
    # noinspection PyPackageRequirements
    from fastnumbers import fast_float, fast_int, __version__ as fn_ver

    # Require >= version 2.0.0.
    if StrictVersion(fn_ver) < StrictVersion("2.0.0"):
        raise ImportError  # pragma: no cover
except ImportError:
    from natsort.compat.fake_fastnumbers import fast_float, fast_int  # noqa: F401
